536:     const active = i === phaseIndex && loop.running && !loop.paused && loop.progress < 100;
537:     return `<div class="loop-step ${done ? "done" : active ? "active" : ""}">
538:       <span class="bullet">${done ? icon("check") : ""}</span>
539:       <span>${esc(phase)}</span>
540:       <span class="step-time">${done ? "✓" : active ? "läuft" : "–"}</span>
541:     </div>`;
542:   }
